// Probe a list of targets in parallel and write a single combined record
// to /data/chatin/_telemetry/. Pure native — node-fetch + fs. The probes are
// FROM-THE-NAS — what the Synology can reach, not what the family devices
// can reach (that's the PWA NetworkStatus component's job). Together they
// tell us whether a failure is on the NAS side or the device side.

const fs = require('fs');
const path = require('path');
const http = require('http');
const https = require('https');

const TELEMETRY_DIR = '/data/chatin/_telemetry';
fs.mkdirSync(TELEMETRY_DIR, { recursive: true });

const TIMEOUT_MS = 5000;

// Targets we care about from the NAS's perspective.
// Note: 'chat' uses the same SYNOLOGY_CHAT_INCOMING_URL env var the chat-post
// nodes use, but we only HEAD/GET to avoid posting noise.
const targets = [
  { key: 'internet', method: 'GET',  url: 'https://www.cloudflare.com/cdn-cgi/trace' },
  { key: 'ollama',   method: 'GET',  url: (process.env.OLLAMA_BASE_URL || 'http://ollama:11434') + '/api/tags' },
  { key: 'n8n_self', method: 'GET',  url: 'http://127.0.0.1:5678/healthz' },
  { key: 'dsm',      method: 'GET',  url: 'http://192.168.1.26:5000/' }
];

function probe({ key, method, url }) {
  return new Promise((resolve) => {
    const started = Date.now();
    try {
      const u = new URL(url);
      const lib = u.protocol === 'https:' ? https : http;
      const req = lib.request({
        method,
        protocol: u.protocol,
        hostname: u.hostname,
        port: u.port || (u.protocol === 'https:' ? 443 : 80),
        path: u.pathname + u.search,
        timeout: TIMEOUT_MS,
        rejectUnauthorized: false // tolerate Synology self-signed certs for internal probes
      }, (res) => {
        const ms = Date.now() - started;
        // Drain to avoid leaving the socket half-open.
        res.on('data', () => {});
        res.on('end', () => {
          resolve({ key, ok: res.statusCode >= 200 && res.statusCode < 500, status: res.statusCode, ms });
        });
      });
      req.on('timeout', () => {
        req.destroy(new Error('timeout'));
      });
      req.on('error', (err) => {
        resolve({ key, ok: false, status: 0, ms: Date.now() - started, error: String(err && err.message || err) });
      });
      req.end();
    } catch (err) {
      resolve({ key, ok: false, status: 0, ms: Date.now() - started, error: String(err && err.message || err) });
    }
  });
}

return (async () => {
  const probedAt = new Date().toISOString();
  const results = await Promise.all(targets.map(probe));

  const summary = {
    probed_at: probedAt,
    results,
    any_failed: results.some(r => !r.ok),
    failed: results.filter(r => !r.ok).map(r => r.key)
  };

  // Persist every run for later analysis (one file per run keeps it simple).
  const safeTs = probedAt.replace(/[:.]/g, '-');
  const filename = path.join(TELEMETRY_DIR, `${safeTs}__probe.json`);
  try { fs.writeFileSync(filename, JSON.stringify(summary, null, 2)); } catch (_) {}

  // Compose a chat message that's only meaningful when something is wrong.
  const lines = ['*NAS-side health · ' + new Date(probedAt).toLocaleTimeString() + '*'];
  for (const r of results) {
    const icon = r.ok ? '🟢' : '🔴';
    const ms = r.ms != null ? ` (${r.ms}ms)` : '';
    const status = r.status ? ` [${r.status}]` : '';
    lines.push(`${icon} ${r.key}${status}${ms}${r.error ? ' — ' + r.error : ''}`);
  }

  return [{
    json: {
      ...summary,
      chat_text: lines.join('\n'),
      should_alert: summary.any_failed
    }
  }];
})();

// All probes green — quiet path. Return a no-op marker so the execution
// log shows why we didn't post (and we can search for 'all-green' to see
// healthy runs).
return [{ json: { skipped: true, reason: 'all-green-or-url-missing', ...$input.first().json } }];
